/**
 * Common utility types for NeuroLink
 */
/**
 * Type-safe unknown value - use when type is truly unknown
 */
export type Unknown = unknown;
/**
 * Type-safe record for metadata and configuration objects
 */
export type UnknownRecord = Record<string, unknown>;
/**
 * Type-safe array of unknown items
 */
export type UnknownArray = unknown[];
/**
 * JSON-serializable value type
 */
export type JsonValue = string | number | boolean | null | JsonObject | JsonArray;
export interface JsonObject {
    [key: string]: JsonValue;
}
export interface JsonArray extends Array<JsonValue> {
}
/**
 * Type-safe error handling
 */
export interface ErrorInfo {
    message: string;
    code?: string | number;
    stack?: string;
    cause?: unknown;
}
/**
 * Generic success/error result type
 */
export interface Result<T = unknown, E = ErrorInfo> {
    success: boolean;
    data?: T;
    error?: E;
}
/**
 * Function parameter type for dynamic functions
 */
export interface FunctionParameters {
    [key: string]: unknown;
}
/**
 * Generic async function type
 */
export type AsyncFunction<TParams = FunctionParameters, TResult = unknown> = (params: TParams) => Promise<TResult>;
/**
 * Sync function type
 */
export type SyncFunction<TParams = FunctionParameters, TResult = unknown> = (params: TParams) => TResult;
/**
 * Union of async and sync functions
 */
export type AnyFunction<TParams = FunctionParameters, TResult = unknown> = AsyncFunction<TParams, TResult> | SyncFunction<TParams, TResult>;
/**
 * Type guard to check if value is Error
 */
export declare function isError(value: unknown): value is Error;
/**
 * Type guard to check if value is ErrorInfo
 */
export declare function isErrorInfo(value: unknown): value is ErrorInfo;
/**
 * Safe error message extraction
 */
export declare function getErrorMessage(error: unknown): string;
/**
 * Safe error conversion
 */
export declare function toErrorInfo(error: unknown): ErrorInfo;
/**
 * NeuroLink Native Event System Types
 */
/**
 * Tool execution event for real-time streaming
 */
export interface ToolExecutionEvent {
    type: "tool:start" | "tool:end";
    tool: string;
    input?: unknown;
    result?: unknown;
    error?: string;
    timestamp: number;
    duration?: number;
    executionId: string;
}
/**
 * Tool execution summary for completed executions
 */
export interface ToolExecutionSummary {
    tool: string;
    startTime: number;
    endTime: number;
    duration: number;
    success: boolean;
    result?: unknown;
    error?: string;
    executionId: string;
    metadata?: {
        serverId?: string;
        toolCategory?: "direct" | "custom" | "mcp";
        isExternal?: boolean;
    };
}
/**
 * Stream event types for real-time communication
 */
export interface StreamEvent {
    type: "stream:chunk" | "stream:complete" | "stream:error";
    content?: string;
    metadata?: JsonObject;
    timestamp: number;
}
/**
 * Enhanced NeuroLink event types
 * Flexible interface to support both typed and legacy event patterns
 */
export interface NeuroLinkEvents {
    "tool:start": unknown;
    "tool:end": unknown;
    "stream:start": unknown;
    "stream:end": unknown;
    "stream:chunk": unknown;
    "stream:complete": unknown;
    "stream:error": unknown;
    "generation:start": unknown;
    "generation:end": unknown;
    "response:start": unknown;
    "response:end": unknown;
    "externalMCP:serverConnected": unknown;
    "externalMCP:serverDisconnected": unknown;
    "externalMCP:serverFailed": unknown;
    "externalMCP:toolDiscovered": unknown;
    "externalMCP:toolRemoved": unknown;
    "externalMCP:serverAdded": unknown;
    "externalMCP:serverRemoved": unknown;
    "tools-register:start": unknown;
    "tools-register:end": unknown;
    connected: unknown;
    message: unknown;
    error: unknown;
    log: unknown;
    [key: string]: unknown;
}
/**
 * TypeScript utility for typed EventEmitter
 * Flexible interface to support both typed and legacy event patterns
 */
export interface TypedEventEmitter<TEvents extends Record<string, unknown>> {
    on<K extends keyof TEvents>(event: K, listener: (...args: unknown[]) => void): this;
    emit<K extends keyof TEvents>(event: K, ...args: unknown[]): boolean;
    off<K extends keyof TEvents>(event: K, listener: (...args: unknown[]) => void): this;
    removeAllListeners<K extends keyof TEvents>(event?: K): this;
    listenerCount<K extends keyof TEvents>(event: K): number;
    listeners<K extends keyof TEvents>(event: K): Array<(...args: unknown[]) => void>;
}
/**
 * Tool execution context for tracking
 */
export interface ToolExecutionContext {
    executionId: string;
    tool: string;
    startTime: number;
    endTime?: number;
    result?: unknown;
    error?: string;
    metadata?: JsonObject;
}
